const idx = parseInt(msg.req.params.idx, 10);
if (!Number.isInteger(idx) || idx < 0) {
  msg.statusCode = 400;
  msg.headers = { 'content-type': 'application/json' };
  msg.payload = { error: 'invalid_idx' };
  return msg;
}

const bits = global.get('loadStatusBits')(Math.ceil((idx + 1) / 8));
global.get('setStatusBit')(bits, idx, true);
global.get('saveStatusBits')(bits);

const registry = global.get('loadRegistry')();
const entry = registry.find((e) => e.idx === idx);
if (entry) {
  entry.revoked = true;
  entry.revokedAt = new Date().toISOString();
  global.get('saveRegistry')(registry);
}

node.log('admin: revoked credential idx=' + idx);
msg.statusCode = 302;
msg.headers = { location: '/admin' };
msg.payload = '';
return msg;

const idx = parseInt(msg.req.params.idx, 10);
if (!Number.isInteger(idx) || idx < 0) {
  msg.statusCode = 400;
  msg.headers = { 'content-type': 'application/json' };
  msg.payload = { error: 'invalid_idx' };
  return msg;
}

const bits = global.get('loadStatusBits')(Math.ceil((idx + 1) / 8));
global.get('setStatusBit')(bits, idx, false);
global.get('saveStatusBits')(bits);

const registry = global.get('loadRegistry')();
const entry = registry.find((e) => e.idx === idx);
if (entry) {
  entry.revoked = false;
  entry.revokedAt = null;
  global.get('saveRegistry')(registry);
}

node.log('admin: restored credential idx=' + idx);
msg.statusCode = 302;
msg.headers = { location: '/admin' };
msg.payload = '';
return msg;
